import {expect} from '@playwright/test';
import {readFileSync} from 'node:fs';
const templates=JSON.parse(readFileSync(new URL('../../src/core/collage-templates.json',import.meta.url),'utf8'));
export async function exerciseBlendWorker(page,module){
 const result=await page.evaluate(async({module,templates})=>{
  const wrapper=URL.createObjectURL(new Blob([`const Base=OffscreenCanvas;self.OffscreenCanvas=class extends Base{constructor(w,h){super(w,h);this.scratch=w===1&&h===1;}get width(){return super.width;}set width(v){super.width=v;if(this.scratch)postMessage({scratchPixels:super.width*super.height});}get height(){return super.height;}set height(v){super.height=v;if(this.scratch)postMessage({scratchPixels:super.width*super.height});}};await import(${JSON.stringify(new URL(module,location.href).href)});postMessage({ready:true});`],{type:'text/javascript'}));const worker=new Worker(wrapper,{type:'module'});let sequence=0,scratchPeak=0;let readyResolve;const ready=new Promise(resolve=>readyResolve=resolve);const pending=new Map();worker.onmessage=({data})=>{if(data.ready){readyResolve();return;}if(data.scratchPixels){scratchPeak=Math.max(scratchPeak,data.scratchPixels);return;}if(data.progress)return;const p=pending.get(data.id);if(!p)return;pending.delete(data.id);data.error?p.reject(Error(data.error)):p.resolve(data.result);};const send=data=>new Promise((resolve,reject)=>{const id=++sequence;pending.set(id,{resolve,reject});worker.postMessage({id,...data});});
  const profile={version:2,extra_orientation:1},file=async(color,id)=>{const c=new OffscreenCanvas(16,16),x=c.getContext('2d');x.fillStyle=color;x.fillRect(0,0,16,16);return {id,file:new File([await c.convertToBlob()],id+'.png'),profile};},pixels=async blob=>{const im=await createImageBitmap(blob),c=new OffscreenCanvas(im.width,im.height),x=c.getContext('2d');x.drawImage(im,0,0);im.close();return x.getImageData(0,0,c.width,c.height).data;},scene=(sources,template,width=317,height=211)=>({version:2,edge_blend:25.5,template,width,height,gap:.017,padding:.031,radius:.16,background:'#00ff00',sources,cells:sources.map(s=>({source_id:s.id,pan:{x:0,y:0},zoom:1}))});
  try{
   await ready;const sources=await send({action:'open',inputs:[await file('#ff0000','red'),await file('#0000ff','blue')]}),s=scene(sources,'2-lr'),out=await send({action:'export',scene:s}),data=await pixels(out.blob);let error=0;
   const pad=s.height*s.padding,center=s.width/2,half=s.edge_blend/2;for(let y=Math.ceil(pad)+2;y<s.height-pad-2;y++)for(let x=Math.ceil(pad)+2;x<s.width-pad-2;x++){const t=Math.max(0,Math.min(1,(x+.5-(center-half))/s.edge_blend)),i=(y*s.width+x)*4;error=Math.max(error,Math.abs(data[i]-255*(1-t)),data[i+1],Math.abs(data[i+2]-255*t),Math.abs(data[i+3]-255));}
   const reversed={...s,sources:[...s.sources].reverse(),cells:[...s.cells].reverse()},swapped=await pixels((await send({action:'export',scene:reversed})).blob);let symmetry=0;for(let y=20;y<190;y++)for(let x=20;x<297;x++){const i=(y*317+x)*4;for(let k=0;k<4;k++)symmetry=Math.max(symmetry,Math.abs(data[i+k]-swapped[(y*317+(316-x))*4+k]));}
   const noBlend={...s,edge_blend:0},legacy={...noBlend,version:1};delete legacy.edge_blend;const zero=await pixels((await send({action:'export',scene:noBlend})).blob),old=await pixels((await send({action:'export',scene:legacy})).blob);const legacyEqual=zero.every((v,i)=>v===old[i]);
   const large={...s,width:3001,height:1801,padding:0,edge_blend:123},full=await send({action:'export',scene:large}),fullData=await pixels(full.blob),preview=await send({action:'render',scene:large,options:{format:'png',quality:95,showGuides:false}}),previewData=await pixels(preview.blob);let largeError=0;
   for(const [bytes,width,height] of [[fullData,3001,1801],[previewData,preview.width,preview.height]])for(let y=1;y<height;y+=Math.max(1,Math.floor(height/31)))for(let x=0;x<width;x++){const t=Math.max(0,Math.min(1,((x+.5)*3001/width-(1500.5-61.5))/123)),i=(y*width+x)*4;largeError=Math.max(largeError,Math.abs(bytes[i]-255*(1-t)),bytes[i+1],Math.abs(bytes[i+2]-255*t));}
   const bandScene={...large,template:'1-full',sources:[sources[0]],cells:[large.cells[0]]},bandPixels=await pixels((await send({action:'export',scene:bandScene})).blob),bandsExact=bandPixels.every((v,i)=>v===(i%4===0||i%4===3?255:0));
   const uniform=[];for(let i=0;i<12;i++)uniform.push(await file('#466e8c','solid-'+i));const all=await send({action:'open',inputs:uniform});let layouts=0,uniformError=0;
   for(const template of templates){const s=scene(all.slice(0,template.cells.length),template.id);s.edge_blend=8;const bytes=await pixels((await send({action:'export',scene:s})).blob);for(let y=10;y<201;y++)for(let x=10;x<307;x++){const i=(y*317+x)*4;uniformError=Math.max(uniformError,Math.abs(bytes[i]-70),Math.abs(bytes[i+1]-110),Math.abs(bytes[i+2]-140));}layouts++;}
   const gap=scene(all.slice(0,2),'2-lr');gap.cells.forEach(c=>c.zoom=.25);const guided=await pixels((await send({action:'render',scene:gap})).blob),clean=await pixels((await send({action:'export',scene:gap})).blob),hidden=await pixels((await send({action:'render',scene:gap,options:{format:'png',quality:95,showGuides:false}})).blob);const guidesDiffer=guided.some((v,i)=>v!==clean[i]),hiddenEqual=hidden.every((v,i)=>v===clean[i]);
   return {error,symmetry,legacyEqual,largeError,layouts,uniformError,guidesDiffer,hiddenEqual,scratchPeak,bandsExact};
  }finally{worker.terminate();URL.revokeObjectURL(wrapper);}
 },{module,templates});
 expect(result.bandsExact).toBe(true);expect(result.scratchPeak).toBeLessThanOrEqual(4_000_000);expect(result.scratchPeak).toBeGreaterThan(3_900_000);expect(result.error).toBeLessThanOrEqual(2);expect(result.symmetry).toBeLessThanOrEqual(1);expect(result.legacyEqual).toBe(true);expect(result.largeError).toBeLessThanOrEqual(2);expect(result.layouts).toBe(80);expect(result.uniformError).toBeLessThanOrEqual(3);expect(result.guidesDiffer).toBe(true);expect(result.hiddenEqual).toBe(true);return result;
}
export async function exerciseBlendUI(page,info,lang){
 const t=(zh,en)=>lang==='en'?en:zh,dialog=page.getByRole('dialog',{name:t('照片拼图','Photo collage'),exact:true}),button=(zh,en)=>dialog.getByRole('button',{name:t(zh,en),exact:true}),field=(zh,en)=>dialog.getByLabel(t(zh,en),{exact:true});
 const bytes=await page.evaluate(async()=>{const c=new OffscreenCanvas(100,60),x=c.getContext('2d'),out=[];for(const color of ['#dd6644','#3377bb']){x.fillStyle=color;x.fillRect(0,0,100,60);out.push([...new Uint8Array(await(await c.convertToBlob()).arrayBuffer())]);}return out;});const files=bytes.map((v,i)=>({name:'Blend-'+i+'.png',mimeType:'image/png',buffer:Buffer.from(v)}));await dialog.locator('input[type=file]').first().setInputFiles(files);await expect(button('保存布局清单','Save layout document')).toBeEnabled();
 await field('画布宽度','Canvas width').fill('600');await field('画布高度','Canvas height').fill('400');await field('画布高度','Canvas height').press('Tab');await field('格子圆角','Cell corners').fill('0.15');await field('接缝融边（像素）','Seam blend (pixels)').fill('40');await field('融边精确宽度','Exact blend width').fill('80');await field('融边精确宽度','Exact blend width').press('Tab');await expect(field('融边精确宽度','Exact blend width')).toHaveValue('80');await expect(dialog.getByText(t('融边会填合内部间距，圆角设置保留但暂不绘制。外边缘不羽化。','Blending joins internal gaps; corner settings are retained but not drawn. Outer edges remain solid.'),{exact:true})).toBeVisible();
 const download=async(zh,en)=>{const event=page.waitForEvent('download');await button(zh,en).click();return readFileSync(await(await event).path());};const document=JSON.parse(await download('保存布局清单','Save layout document'));expect(document).toMatchObject({version:2,edge_blend:80,radius:.15});const blended=await download('导出拼图 PNG','Export collage PNG');
 await button('重置画布设置','Reset canvas settings').click();await expect(field('融边精确宽度','Exact blend width')).toHaveValue('0');await expect(field('画布宽度','Canvas width')).toHaveValue('2400');await button('撤销拼图','Undo collage').click();await expect(field('融边精确宽度','Exact blend width')).toHaveValue('80');expect(await download('导出拼图 PNG','Export collage PNG')).toEqual(blended);
 await dialog.locator('input[type=file]').nth(2).setInputFiles({name:'Blend.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(document))});await dialog.locator('input[type=file]').first().setInputFiles([...files].reverse());await expect(button('导出拼图 PNG','Export collage PNG')).toBeEnabled();expect(await download('导出拼图 PNG','Export collage PNG')).toEqual(blended);
 const legacy={...document,version:1};delete legacy.edge_blend;await dialog.locator('input[type=file]').nth(2).setInputFiles({name:'Old.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(legacy))});await dialog.locator('input[type=file]').first().setInputFiles(files);await expect(field('融边精确宽度','Exact blend width')).toHaveValue('0');await field('融边精确宽度','Exact blend width').fill('80');await field('融边精确宽度','Exact blend width').press('Tab');await expect(dialog.locator('.collage-stage')).toHaveAttribute('aria-busy','false');await dialog.evaluate(e=>e.scrollTop=0);await dialog.screenshot({path:info.outputPath('collage-blend-'+lang+'.png')});if(lang==='en')expect(await dialog.innerText()).not.toMatch(/[\u3400-\u9fff]/);expect(await dialog.evaluate(e=>e.scrollWidth<=e.clientWidth+1)).toBe(true);page.once('dialog',d=>d.accept());await button('关闭','Close').click();await expect(dialog).toHaveCount(0);
}
